use vstd::prelude::*;

verus! {

    // specification function to count the number of true entries in a boolean sequence
    spec fn count_true(condition: Seq<bool>) -> int
        decreases condition.len()
    {
        if condition.len() == 0 {
            0
        } else {
            let head = condition.index(0);
            let tail = condition.slice(1, condition.len());
            (if head { 1 } else { 0 }) + count_true(tail)
        }
    }

    // extract elements from `arr` where the corresponding entry in `condition` is true
    fn extract(condition: Vec<bool>, arr: Vec<f32>) -> (result: Vec<f32>)
        requires
            condition.len() == arr.len(),
        ensures
            // the length of the output vector equals the number of true's in the mask
            result.len() as int == count_true(condition@),
    {
        let n: usize = condition.len();
        let mut i: usize = 0;
        let mut result: Vec<f32> = Vec::new();
        // loop over all positions 0..n
        while i < n
            invariant
                0 <= i && i <= n,
                // at each step, result.len() equals the count of true's in the prefix condition[0..i]
                result.len() as int == count_true(condition@.slice(0, i)),
            decreases n - i,
        {
            // read the i-th boolean
            let bit: bool = condition.index(i);
            if bit {
                // if it's true, then the count_true of the longer prefix increases by 1
                proof {
                    // count_true(condition[0..i+1]) == count_true(condition[0..i]) + 1
                    let prefix = condition@.slice(0, i);
                    let longer = condition@.slice(0, i + 1);
                    assert(count_true(longer) == count_true(prefix) + 1);
                }
                // push the corresponding element of arr into result
                let x: f32 = arr.index(i);
                result.push(x);
            } else {
                // if it's false, the count_true does not change
                proof {
                    let prefix = condition@.slice(0, i);
                    let longer = condition@.slice(0, i + 1);
                    assert(count_true(longer) == count_true(prefix));
                }
                // do nothing with result
            }
            i = i + 1;
        }
        // now i == n, so slice(0,n) is the whole sequence
        result
    }
}

fn main() {
    // example usage (not part of the proof):
    let cond = vec![true, false, true];
    let arr  = vec![1.0f32, 2.0, 3.0];
    let out  = extract(cond.clone(), arr.clone());
    assert!(out.len() == 2);
    assert!(out[0] == 1.0 && out[1] == 3.0);
}